/**
 * Hand-authored round-2 flashcards filling the coverage gaps the card
 * generator's --plan reported (115 cards across ENG, PE, BIO, PSY —
 * complex_familiar and complex_unfamiliar bands only; simple recall is
 * already dense everywhere).
 *
 * Written by hand against the real learning objectives pulled from the
 * database (scripts/dump-objectives.ts output), because the Anthropic key
 * had no credits when generate-cards.ts ran. NOT generated — no AI provider
 * is called anywhere in this file.
 *
 * Run:  npx tsx scripts/seed-cards-round2.ts [--write] [ENG PE BIO PSY]
 *
 * Same machinery as seed-cards-eng-pe.ts: dry run by default, idempotent on
 * front-text, saves through saveCards().
 */
import { config } from "dotenv";
config({ path: ".env.local" });

import { PrismaClient } from "../src/generated/prisma/client";
import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import type { ComplexityBand } from "../src/lib/cards";

async function deps() {
  const cards = await import("../src/lib/cards");
  return cards;
}

const prisma = new PrismaClient({
  adapter: new PrismaBetterSqlite3({ url: process.env.DATABASE_URL! }),
});

type SeedCard = {
  front: string;
  back: string;
  complexity: ComplexityBand;
  cardType?: "basic" | "cloze";
};

// ============================================================================
// ENGLISH — U3T1: Conversations about issues in texts (need CF 9, CU 7)
// ============================================================================
const ENG_U3T1: SeedCard[] = [
  { complexity: "complex_familiar", front: "Explain what it means for texts about the same social issue to be 'in conversation' (dialogic), and why this matters for analysis. (3 marks)", back: "1 mark: Texts respond to, echo, extend or challenge ideas raised in other texts on the issue — meaning is built between texts, not just within one. 1 mark: An analysis must therefore consider what positions a text is answering or resisting. 1 mark: E.g. an opinion column may only make full sense as a rebuttal of an earlier editorial — its emphasis and tone are shaped by the prior text." },
  { complexity: "complex_familiar", front: "Explain how the SAME social issue can be represented in opposite ways by two news outlets. Use the concepts of selection and emphasis. (3 marks)", back: "1 mark: Representation is constructed, not a mirror — producers select which facts, voices and images to include. 1 mark: Emphasis (headline placement, ordering, space given) privileges one perspective and marginalises others. 1 mark: The same protest can be framed as 'community outrage' (voices of protesters foregrounded) or 'city disruption' (voices of commuters foregrounded)." },
  { complexity: "complex_familiar", front: "Explain how modality choices can construct or undermine authority in a persuasive text about an issue. (3 marks)", back: "1 mark: High modality ('must', 'will', 'undeniably') presents claims as certain, constructing an authoritative, decisive voice. 1 mark: Low modality ('might', 'could', 'perhaps') hedges claims — it can appear balanced and reasonable, or weak and uncommitted, depending on context. 1 mark: Strategic mixing works best: high modality on the core contention, lower modality when conceding minor points, so the writer seems both strong and fair." },
  { complexity: "complex_familiar", front: "A speech uses an anecdote about one affected family instead of statistics about thousands. Explain the persuasive trade-off. (3 marks)", back: "1 mark: The anecdote personalises the issue — audiences empathise with a named individual (pathos) far more than with abstract numbers. 1 mark: Trade-off: one story is not representative; a critical audience may see it as cherry-picked, weakening logos. 1 mark: Strong texts pair the two — the anecdote creates emotional investment, the statistic proves the story is typical." },
  { complexity: "complex_familiar", front: "Explain how a text 'establishes and maintains a relationship' with its audience, giving two concrete techniques. (3 marks)", back: "1 mark: A text builds a relationship by positioning the reader as a valued insider whose concerns and values the writer shares. 1 mark: Technique 1 — inclusive pronouns and shared-value appeals ('we all want our kids safe') align reader and writer. 1 mark: Technique 2 — direct address and rhetorical questions ('Have you noticed...?') simulate dialogue, keeping the reader actively engaged rather than passively receiving." },
  { complexity: "complex_familiar", front: "Explain how personal, social, historical and cultural context each shape the MEANING a text about an issue carries. (4 marks)", back: "1 mark each: Personal — a reader's own experiences (e.g. of unemployment) intensify or dull a text's impact. Social — prevailing attitudes of the reader's community shape which arguments feel legitimate. Historical — a text about war reads differently before and after a major conflict; references gain or lose force. Cultural — assumptions about gender, class or religion embedded in the text land differently across cultures, which is why the 'same' text produces different meanings for different audiences." },
  { complexity: "complex_familiar", front: "Why can an omission be as persuasive as anything actually stated in a media text? (2 marks)", back: "1 mark: What is left out never gets to contest the framing — an unrepresented perspective cannot defend itself, so the included view stands unchallenged. 1 mark: Omission is invisible to casual audiences; unlike overt argument, it persuades without appearing to persuade, making it harder to resist." },
  { complexity: "complex_familiar", front: "Explain how emerging technologies and the changing media landscape have shifted the way public 'conversations' about issues happen. (3 marks)", back: "1 mark: Publication is no longer gatekept — social media lets anyone contribute a representation, multiplying perspectives (and misinformation). 1 mark: Algorithms curate feeds toward engagement, amplifying emotive framings and creating echo chambers where one representation dominates. 1 mark: Audiences are now also producers — commenting, sharing and remixing texts, so the 'conversation' is faster, more fragmented and less controlled by institutions." },
  { complexity: "complex_familiar", front: "Distinguish ethos, pathos and logos, and give a one-line example of each in a campaign speech about road safety. (3 marks)", back: "1 mark: Ethos — credibility of the speaker: 'As a paramedic of 20 years, I've seen what speed does.' 1 mark: Pathos — appeal to emotion: 'No parent should get that knock on the door.' 1 mark: Logos — appeal to logic/evidence: 'Lowering limits by 10 km/h cut fatalities 23% in comparable cities.'" },
  { complexity: "complex_unfamiliar", front: "A charity releases two versions of the same fundraising appeal: a TV ad using a child's voice, slow piano music and one repeated statistic, and a LinkedIn post using formal register, four statistics and a policy proposal. Analyse how mode and audience explain the different constructions, and evaluate which is more likely to achieve its purpose. (6 marks)", back: "Model response: The TV ad targets a broad domestic audience in an emotional, low-attention viewing context — the child's voice and music are aural techniques unique to the mode, engineered for pathos, while the single repeated statistic respects limited attention and aids recall. The LinkedIn post targets professionals in a rational, reputational context: formal register and layered statistics build ethos and logos for an audience primed to evaluate arguments, and the policy proposal converts persuasion into professional action. Neither is 'more manipulative' — each calibrates technique to mode and audience. Evaluation: each is more likely to succeed with its own target; if forced to judge, the TV ad better achieves a fundraising purpose because donations are emotion-driven decisions, while the LinkedIn post better achieves advocacy. Marking points: (1) identifies mode-specific techniques in the ad; (2) identifies register/evidence choices in the post; (3) links each to its audience's context and values; (4) links each to purpose; (5) makes an explicit evaluative judgement; (6) justifies the judgement rather than asserting it." },
  { complexity: "complex_unfamiliar", front: "A politician's maiden speech frames housing affordability through their own story of growing up in public housing. A think-tank report the same week frames it through supply-and-demand modelling. A reader says: 'The speech is biased; the report is objective.' Challenge this claim using the concept of representation. (5 marks)", back: "Model response: Both texts are constructed representations — neither is a neutral window. The speech openly signals its perspective through personal narrative, making its positioning visible; its 'bias' is legible. The report's objectivity is itself a construction: choosing economic modelling as the frame privileges market-based causes and solutions while marginalising lived experience, and its formal register and passive constructions conceal that authorial choices were made. The report's selection of variables, data ranges and terminology all embody a perspective. The real distinction is not biased/objective but visible positioning vs. naturalised positioning — and naturalised positioning is arguably more persuasive because audiences don't resist what they don't notice. Marking points: (1) states both are representations; (2) explains how the speech's positioning is overt; (3) explains how the report's frame embodies choices; (4) identifies register/genre features that construct 'objectivity'; (5) reframes the distinction (visible vs naturalised) rather than accepting biased/objective." },
  { complexity: "complex_unfamiliar", front: "You are creating a persuasive spoken text opposing a new development on local wetlands, to be delivered at a council meeting where most councillors are undecided and budget-conscious. Devise your rhetorical strategy: choose and justify a register, two appeals, and one structural choice. (5 marks)", back: "Model response: Register — measured formal register with moments of controlled passion: councillors are a professional audience who distrust ranting, but pure formality wastes the spoken mode's emotional potential. Appeal 1 — logos targeted at their budget concern: quantify the wetlands' flood-mitigation value and the cost of engineered drainage replacing it, converting 'environment vs economy' into 'economy vs economy'. Appeal 2 — ethos by association: cite the council's own published environment strategy, positioning opposition to the development as consistency with their commitments, not activism. Structural choice — concession-rebuttal early: acknowledge the housing need the development claims to serve, then show alternative sites meet it; pre-empting the strongest counterargument in front of undecided listeners disarms it before proponents speak. Marking points: (1) register chosen and justified against audience; (2) each appeal linked to the specific audience's values; (3) appeals are distinct (not two versions of pathos); (4) structural choice named and justified; (5) strategy coheres as a whole for the undecided-councillor context." },
  { complexity: "complex_unfamiliar", front: "A documentary about fast fashion includes interviews with garment workers, an economist, and a brand CEO — but the CEO's interview is intercut with footage of factory conditions that contradict his words. Analyse how editing constructs meaning here, and discuss whether the documentary can still claim balance. (5 marks)", back: "Model response: The intercutting is a juxtaposition technique: placing the CEO's claims beside contradicting images invites the audience to read him as dishonest without the narrator saying so — the meaning is constructed in the edit, positioning viewers to distrust one voice while appearing to 'let him speak'. Formally the documentary includes all stakeholders, satisfying surface balance; functionally, editing assigns credibility unequally, so the represented perspectives are not equally empowered. Discussion: it can claim inclusiveness but not neutrality — balance is not just presence of voices but equivalence of framing. This may still be defensible if the footage is authentic; representation can be persuasive and truthful simultaneously, but the claim 'balanced' overstates it. Marking points: (1) identifies juxtaposition/intercutting as the technique; (2) explains how it positions the audience against the CEO; (3) distinguishes surface balance (inclusion) from framing equivalence; (4) makes a judgement on the balance claim; (5) supports the judgement with the authenticity/persuasion distinction." },
  { complexity: "complex_unfamiliar", front: "Two weeks after a flood, a tabloid runs the headline 'ABANDONED: Families left to drown while officials dithered' with a photo of a crying resident. Deconstruct the representation: identify three specific choices and the cumulative way they position the audience, then propose how a broadsheet might report the same facts differently. (6 marks)", back: "Model response: Choice 1 — 'ABANDONED' in caps: emotive, absolute lexis asserting neglect as fact, not allegation. Choice 2 — 'left to drown' vs 'officials dithered': agency is assigned asymmetrically; residents are passive victims, officials are culpable actors, collapsing a complex emergency into villain/victim. Choice 3 — the crying-resident photo: pathos anchoring the verbal claims in a human face, making scepticism feel callous. Cumulatively, the audience is positioned as outraged on behalf of victims, primed to demand accountability before evidence is assessed. A broadsheet version might read 'Questions raised over flood response times' with a photo of floodwaters: nominalisation ('questions raised') removes the accuser, modality drops from certainty to inquiry, and the image documents rather than emotes — positioning readers as evaluators, not avengers. Marking points: (1)–(3) three choices identified with technique named; (4) cumulative positioning stated; (5) broadsheet alternative offered with changed techniques; (6) explains how the alternative repositions the audience." },
  { complexity: "complex_unfamiliar", front: "A viral post claims 'they don't want you to know' about a health issue, mixing real studies with unsourced claims, and gains more engagement than the official health authority's page. Using ideas about rhetoric, audience relationships and the changing media landscape, explain WHY the post outperforms the authority — and what this reveals about power in contemporary public conversations. (6 marks)", back: "Model response: The post wins rhetorically: 'they don't want you to know' constructs an intimate insider relationship — reader and writer allied against a shadowy establishment — which is a stronger relational hook than the authority's one-to-many institutional address. Mixing real studies with unsourced claims borrows ethos from science while evading its constraints. Algorithmically, outrage and secrecy drive shares, so the platform amplifies the more emotive construction regardless of accuracy. The authority is structurally disadvantaged: obligated to hedge (accurate low modality reads as uncertainty), forbidden the conspiratorial intimacy that builds parasocial trust. This reveals that power in public conversations has partly shifted from institutional authority (credentials, gatekeeping) to attention capture (emotional resonance, relatability) — persuasive power now rewards mastery of audience relationship over mastery of evidence. Marking points: (1) analyses the insider-relationship construction; (2) identifies the borrowed-ethos technique; (3) brings in the algorithmic/media-landscape dimension; (4) explains the authority's structural constraints; (5) draws the power conclusion; (6) sustains linkage between techniques and the 'why' question rather than describing the post." },
  { complexity: "complex_unfamiliar", front: "A supermarket chain's ad campaign about 'supporting Aussie farmers' runs while news breaks that the same chain is cutting farm-gate prices. Analyse how the campaign's representation works, how the news recontextualises it, and what a critical audience should do with the collision of the two texts. (5 marks)", back: "Model response: The campaign constructs the chain as ally and patriot: golden-hour imagery of farm families, first-name storytelling, and inclusive nationalism ('Aussie') invite the audience to experience purchasing as loyalty — the representation converts a commercial relationship into a moral community, and its warmth pre-empts scrutiny. The news story recontextualises every element: the same images now read as strategic cover, the first-name intimacy as appropriation of the very people being squeezed, so the texts enter direct dialogue — meaning made between them, not in either alone (the dialogic principle). The gap between representation and reported practice is itself the meaning: the campaign becomes evidence of what the chain wants believed precisely where its conduct is weakest. A critical audience should read laterally: treat the ad as a positioned text with commercial purpose, weigh it against independently produced texts, notice what the campaign omits (prices paid, contracts), and recognise that emotional resonance is not evidence — while also not treating the news framing as neutral; it too selects and emphasises. Marking points: (1) analyses the campaign's techniques and positioning; (2) explains recontextualisation by the news text; (3) applies the dialogic/between-texts principle; (4) identifies omission as meaningful; (5) critical-audience response includes scepticism toward BOTH texts." },
];

// ============================================================================
// ENGLISH — U3T2: Conversations about concepts in texts (need CF 12, CU 7)
// ============================================================================
const ENG_U3T2: SeedCard[] = [
  { complexity: "complex_familiar", front: "Explain how intertextual links contribute to meaning-making, with one concrete example. (3 marks)", back: "1 mark: A text that references another imports the earlier text's meanings, so the reader's knowledge of the source becomes part of the new text's meaning. 1 mark: The link can honour, complicate or subvert the source — the relationship itself carries meaning. 1 mark: E.g. a novel titled after a Bible verse invites reading its events against that verse; irony emerges if the events betray the verse's promise." },
  { complexity: "complex_familiar", front: "Explain the difference between an aesthetic feature and a stylistic device, and why examiners want their EFFECTS analysed rather than identified. (3 marks)", back: "1 mark: Aesthetic features are elements appealing to sensory/artistic appreciation (imagery, rhythm, visual design); stylistic devices are an author's characteristic techniques (recurring motif, syntax patterns, narrative voice) — overlapping but not identical categories. 1 mark: Identification only proves recognition — the analytical skill is explaining what the feature DOES to interpretation and engagement. 1 mark: Full-mark analysis links device → effect → meaning: 'the fragmented sentences (device) mimic the narrator's panic (effect), positioning readers inside her disintegrating certainty (meaning)'." },
  { complexity: "complex_familiar", front: "Explain how the same concept (e.g. 'working life') can be represented in contrasting ways in texts from different times and places. (3 marks)", back: "1 mark: Each text's context supplies different assumptions — an industrial-era novel may represent work as bodily endurance and class fate; a contemporary text as identity and self-fulfilment. 1 mark: Language and genre choices encode these assumptions (grim naturalistic detail vs. ironic office comedy). 1 mark: Comparing them exposes what each context takes for granted — the comparison reveals cultural values that neither text states directly." },
  { complexity: "complex_familiar", front: "What does it mean to 'question the assumptions and values' in a text? Outline the process with an example about gender. (3 marks)", back: "1 mark: Identify what the text treats as natural or unremarkable — what it never argues for because it assumes it. 1 mark: Ask who benefits from that assumption and whose perspective it marginalises. 1 mark: E.g. a text where female characters exist only in relation to male protagonists assumes women's stories are peripheral; questioning it means noticing the pattern, naming the value it encodes, and considering how the text would change if the assumption were reversed." },
  { complexity: "complex_familiar", front: "Explain why a reader's interpretation of a text can legitimately change on rereading years later. (3 marks)", back: "1 mark: Meaning is made in the transaction between text and reader, not fixed in the text — the words are constant, the reader is not. 1 mark: New personal context (age, experiences, losses) makes different elements salient; a subplot about grief invisible at 15 dominates at 40. 1 mark: New cultural context also shifts readings — a character once read as comic may read as cruel after social attitudes change. Both readings can be textually grounded and legitimate." },
  { complexity: "complex_familiar", front: "Explain how genre conventions can be 'challenged, manipulated and changed over time', and the effect on audiences. (3 marks)", back: "1 mark: Conventions are audience expectations built by repetition — a writer can invoke them and then break them (the detective fails; the fairy-tale ending is refused). 1 mark: The breach is meaningful BECAUSE the expectation exists: audiences feel the deviation and must interpret it. 1 mark: Over time, popular subversions become new conventions themselves (the anti-hero), showing genre as an evolving conversation between texts and audiences." },
  { complexity: "complex_familiar", front: "Distinguish 'perspective' from 'representation' as analytical terms. (2 marks)", back: "1 mark: A perspective is a way of seeing — the position or worldview from which something is viewed (the text's or a character's). 1 mark: A representation is the constructed portrayal itself — the product of choices in language and form that embodies a perspective. A text constructs representations THAT convey perspectives." },
  { complexity: "complex_familiar", front: "How do 'privileged' and 'marginalised' perspectives operate within a single literary text? Give an example mechanism. (3 marks)", back: "1 mark: Privileged perspectives get narrative resources: focalisation, interiority, space, sympathetic framing — the text invites alignment with them. 1 mark: Marginalised perspectives are filtered, silenced or stereotyped — seen only from outside, given no interiority. 1 mark: Mechanism example: first-person narration privileges the narrator's reading of every event; other characters exist only as the narrator constructs them, so their 'voice' is never actually theirs." },
  { complexity: "complex_familiar", front: "Explain how cultural assumptions in a text can help readers 'understand and empathise with the worlds of others'. (2 marks)", back: "1 mark: A text embeds its culture's values in details of daily life, relationships and conflict — reading it is guided immersion in another framework of meaning. 1 mark: Empathy comes from experiencing events THROUGH those assumptions (via focalised characters) rather than observing them from outside — the reader temporarily inhabits, not just inspects, the other world." },
  { complexity: "complex_familiar", front: "Why must textual evidence be 'synthesised' rather than quoted in sequence in an analytical response? (2 marks)", back: "1 mark: Synthesis means multiple pieces of evidence are integrated to support one developing argument — each quote is interpreted and connected to the thesis, and to each other. 1 mark: Sequential quoting ('quote-dumping') demonstrates retrieval, not interpretation; the marks live in the reasoning BETWEEN the quotes — pattern, contrast, accumulation." },
  { complexity: "complex_familiar", front: "Explain what cohesive devices do in an analytical essay and give three distinct types. (3 marks)", back: "1 mark: They make the argument's logic visible — signalling how each part relates to the thesis and to what came before, so ideas read as one developing case. 1 mark: Types: connectives signalling relationship (however, consequently, similarly); referencing chains (this contradiction, such imagery) that carry an idea forward. 1 mark: Structural cohesion: topic sentences that echo the thesis and end-of-paragraph links that hand off to the next point." },
  { complexity: "complex_familiar", front: "A student writes about a text's concept using only plot summary plus the word 'theme'. Explain what's missing against the objective 'analyse how representations of concepts are constructed'. (3 marks)", back: "1 mark: 'Constructed' demands attention to HOW — the language features, structural choices and conventions that build the representation, none of which plot summary touches. 1 mark: Naming a theme identifies WHAT the text is about; analysis requires how choices shape the reader's understanding of it. 1 mark: Fix: for each claim about the concept, cite a specific choice (motif, narrative structure, register) and explain its effect on how the concept is understood." },
  { complexity: "complex_unfamiliar", front: "A modern novel retells a canonical fairy tale from the villain's perspective. Analyse how this intertextual strategy constructs new meaning, and discuss what it suggests about the original's assumptions. (5 marks)", back: "Model response: The retelling depends on the original: readers arrive knowing the 'official' story, so every divergence reads as correction or revelation. Giving the villain focalisation and interiority converts a function (obstacle) into a subject with motives, constructing sympathy where the original assigned only fear. The strategy exposes the original's assumptions: that its hero's perspective was the natural one, that evil needed no explanation — the retelling reveals these as choices, not truths. It also implies a politics of storytelling: whoever narrates, wins; the original marginalised this voice, and the new text models how perspective distributes moral status. New meaning is thus double: a fresh story AND a critique of how the old story was told. Marking points: (1) explains reader's prior knowledge as raw material; (2) analyses focalisation/interiority as the construction technique; (3) names an assumption in the original exposed by the retelling; (4) articulates the narration-power insight; (5) frames meaning as both story and critique." },
  { complexity: "complex_unfamiliar", front: "Two poems fifty years apart both use the sea as a central image — one as divine order, one as indifferent chaos. Write the analytical framework you would use to compare how each constructs its concept, naming the categories of evidence you would collect. (5 marks)", back: "Model response — framework: (1) Imagery patterning: catalogue each poem's sea-adjacent images and their connotations (storm as wrath vs. storm as weather) — establishes the core representational contrast. (2) Form and sound: metre, rhyme and stanza regularity may enact order in the first (regular form = ordered cosmos) and fracture in the second (free verse = chaos); form as meaning, not decoration. (3) Speaker positioning: where is the human relative to the sea — addressed by it, protected from it, ignored by it? This carries each poem's concept of humanity's place. (4) Contextual frame: what beliefs available in each era (religious cosmology vs. post-war disillusion) does each poem assume or contest? (5) Evaluative synthesis: judge whether the difference is contradiction or conversation — the later poem may deliberately answer the earlier tradition. Marking points: (1)–(4) four distinct, genuinely analytical categories; (5) framework moves beyond listing to synthesis; categories connect textual detail to concept construction rather than pure context speculation." },
  { complexity: "complex_unfamiliar", front: "A reader from a collectivist culture and a reader from an individualist culture interpret the same novel's ending — a protagonist leaving her family to pursue art — in opposite ways. Explain how BOTH readings can be textually valid, and what this reveals about where meaning 'lives'. (5 marks)", back: "Model response: The individualist reading sees triumph: the text's imagery of open roads and light, and the arc from constraint to freedom, support self-actualisation as the ending's meaning. The collectivist reading sees loss: the same ending's departure scenes, the mother's silence, the empty table — also in the text — support abandonment and broken obligation. Both cite real features; they differ in which features they weight, and weighting is supplied by the reader's cultural framework of value (autonomy vs. relational duty). Validity requires textual grounding, which both have; neither exhausts the text, which sustains both patterns simultaneously — arguably deliberately. This shows meaning lives neither wholly in the text (or readings couldn't differ) nor wholly in readers (or readings couldn't be tested against evidence) but in the transaction between them — texts constrain the range of valid readings without dictating one. Marking points: (1) grounds reading A in textual features; (2) grounds reading B in textual features; (3) locates the difference in cultural weighting, not error; (4) applies a validity test (textual grounding); (5) draws the transactional conclusion about meaning." },
  { complexity: "complex_unfamiliar", front: "You must write a public-audience piece sustaining your interpretation of a literary text while engaging readers in a 'conversation' about it. Devise your approach: one structural choice, one stylistic choice, and one way you will handle readers who interpret the text differently. (5 marks)", back: "Model response: Structural choice — open with the interpretive problem, not the thesis: pose the moment in the text that divides readers ('Why does she burn the letters?') to recreate the experience of puzzling over it, positioning readers as fellow inquirers before advancing my reading. Stylistic choice — first-person critical voice with concrete textual anchoring: 'I kept returning to the third chapter's silence' models interpretation as lived engagement, warmer than impersonal analysis but still evidence-bound, suited to a public (non-examiner) audience. Handling other readings — concede and convert: name the rival interpretation fairly, identify the textual evidence it explains BETTER than mine, then show what it leaves unexplained that mine accounts for — treating disagreement as the conversation itself rather than an obstacle. Marking points: (1) structural choice named and justified for a public audience; (2) stylistic choice creates voice while retaining evidence; (3) rival readings engaged, not dismissed; (4) all three choices serve the 'conversation' purpose; (5) approach coheres — inquiry frame, personal voice and concession work together." },
  { complexity: "complex_unfamiliar", front: "A play written in 1950 contains attitudes now considered offensive, yet is still taught and performed. One director cuts the offensive lines; another keeps them and adds program notes. Evaluate both responses using the concepts of context, textual integrity and the changing reception of texts. (6 marks)", back: "Model response: Cutting updates the text for its new reception context — protecting audiences and keeping the play performable — but it compromises textual integrity: the offensive attitudes may be structurally load-bearing (what the play reveals about its era, or what a character's prejudice makes the plot mean), and removal quietly falsifies the historical record of what the text was. Keeping with framing preserves integrity and treats the audience as capable of contextual reading: the notes reposition the offensive content from endorsed to exhibited, converting the play into both artwork and historical document. Its risk: framing may not reach every audience member, and harm in the moment is real regardless of intent. Evaluation: the second approach better serves the syllabus insight that responses to texts legitimately change across contexts — the play can be preserved AND read critically; the first approach solves discomfort by pretending the past text was already acceptable. A qualified judgement: keep-and-frame as default, cut where offence is incidental (not meaning-bearing). Marking points: (1) analyses cutting's benefit; (2) analyses cutting's integrity cost; (3) analyses framing's mechanism (endorsed→exhibited); (4) acknowledges framing's risk; (5) makes a justified judgement; (6) qualifies it with the meaning-bearing distinction." },
  { complexity: "complex_unfamiliar", front: "Two students disagree: A says 'the author's intention decides what the text means'; B says 'the author is irrelevant — only the words matter'. Adjudicate, drawing on how contexts of production AND reception both influence meaning. (5 marks)", back: "Model response: A's position captures something real: contexts of production — the author's world, purposes and available meanings — shape the text's construction, and knowing them illuminates choices (why this genre, this omission). But intention cannot 'decide' meaning: authors cannot control connotation, cannot foresee future reception contexts, and texts demonstrably generate meanings their authors disclaim. B's position rightly makes the text the shared evidence base but overcorrects: words never operate context-free — the 'same words' meant differently in 1950 than now, so excluding context doesn't neutralise it, it just smuggles in the reader's own unexamined context. Adjudication: meaning emerges from text-in-context — production context informs (a constraint on plausible readings), reception context activates (different eras foreground different meanings), and the words arbitrate which readings are sustainable. Both absolutist positions fail the same way: each tries to fix meaning at a single point in a process that is relational. Marking points: (1) steelmans A via production context; (2) refutes intention-as-decider; (3) steelmans B via textual evidence; (4) refutes context-free words; (5) synthesises the transactional adjudication." },
  { complexity: "complex_unfamiliar", front: "A picture book and a dystopian novel both explore the concept of surveillance. Your task is to compare how each text's FORM shapes what it can say about the concept. Analyse the affordances and limits of each form, and conclude with what the comparison reveals about form–meaning relationships. (5 marks)", back: "Model response: The picture book's affordances: the word–image gap lets it say two things at once — reassuring text over unsettling images (eyes in every window the words never mention) — so surveillance can be rendered as felt atmosphere a child character normalises, enacting for readers how watching becomes invisible; its economy forces the concept into one resonant symbol. Its limits: minimal space for systemic explanation — it can make surveillance felt but hardly argued. The novel's affordances: extended interiority shows self-censorship developing over time — the reader lives inside a mind learning to pre-edit itself, which is surveillance's deepest operation; world-building can trace institutional machinery, cause and consequence. Its limits: everything arrives through language, so the wordless creep the picture book achieves in a single spread must be told, risking abstraction. The comparison reveals form is not a container for meaning but a condition of it: each form doesn't just present the concept differently — each can KNOW different things about it (felt normalisation vs systemic internalisation), so 'the same concept in two texts' is really two adjacent concepts shaped by what each form makes sayable. Marking points: (1) picture-book affordances via word–image relationship; (2) its limits; (3) novel's affordances via interiority/scale; (4) its limits; (5) the concluding form-conditions-meaning insight, argued not asserted." },
];

// ============================================================================
// ENGLISH — U4T1: Creative responses to literary texts (need CF 11, CU 7)
// ============================================================================
const ENG_U4T1: SeedCard[] = [
  { complexity: "complex_familiar", front: "In a creative response to a literary text, what does 'intervening in the text' mean? Give two forms an intervention can take. (3 marks)", back: "1 mark: Deliberately re-entering the original to alter an element — perspective, gap, timeline, ending — so the new text speaks back to the original's construction of meaning. 1 mark: Form 1 — perspective shift: retelling events through a marginalised or minor character, exposing what the original's focalisation hid. 1 mark: Form 2 — gap-filling: writing a scene the original omits (the years off-stage, the unheard letter), which requires interpreting the original to decide what plausibly fills the silence." },
  { complexity: "complex_familiar", front: "Why must a strong creative response demonstrate ANALYSIS of the original text, even though it is imaginative writing? (3 marks)", back: "1 mark: The creative choices only carry meaning in relation to the original — choosing whose voice to add or which gap to fill IS an interpretive claim about the original. 1 mark: Markers assess the 'conversation' between texts: the response must show it understands the original's representations, values and techniques well enough to manipulate them purposefully. 1 mark: Without that grounding, the piece is free-standing fiction — competent, but not a RESPONSE." },
  { complexity: "complex_familiar", front: "Explain how changing the narrative perspective of a scene repositions the audience. (3 marks)", back: "1 mark: Perspective controls access — whose thoughts we enter, whose reading of events we receive; changing it redistributes knowledge and sympathy. 1 mark: Events keep their facts but change their meaning: the 'rescue' focalised through the rescued may become coercion. 1 mark: The audience is repositioned from alignment with the original's privileged perspective to alignment with a new one — and made aware that the original WAS a perspective, not the truth." },
  { complexity: "complex_familiar", front: "What does it mean for meaning to change 'when a text is transformed into a different genre or medium'? Give one concrete effect. (2 marks)", back: "1 mark: Each genre/medium has its own conventions, affordances and audience expectations, so the 'same' story is reconstructed by different meaning-making resources. 1 mark: E.g. adapting a first-person novel to film loses interior monologue — the camera externalises, so a character's private irony must become visible action or be lost, shifting how the audience judges them." },
  { complexity: "complex_familiar", front: "Explain the difference between imitating a text's style and engaging with its values in a creative response. (3 marks)", back: "1 mark: Imitation reproduces surface features — syntax, imagery, register — demonstrating stylistic control ('sounds like the original'). 1 mark: Engaging with values means the new text takes a position on the original's assumptions — extending, complicating or contesting them. 1 mark: The strongest responses do both: pastiche the style WHILE redirecting it (e.g. the original's elegant register narrating a perspective the original ignored — the style becomes ironic)." },
  { complexity: "complex_familiar", front: "How do aesthetic features in an imaginative text prompt 'critical and emotional responses' simultaneously? (3 marks)", back: "1 mark: Emotional: features like imagery, rhythm and sensory detail work directly on feeling — dread, tenderness, unease — before conscious analysis. 1 mark: Critical: patterned features (recurring motif, structural echo, symbol) invite interpretation — the reader notices design and asks what it means. 1 mark: The two interact: emotion draws investment that motivates interpretation, and interpretation deepens emotional resonance — good imaginative writing engineers both channels deliberately." },
  { complexity: "complex_familiar", front: "A student's creative response fills a gap in a novel but contradicts established facts of the original. Why does this matter, and what is the exception? (2 marks)", back: "1 mark: It matters because a response's authority comes from fidelity to the original's world — unearned contradiction reads as misreading, breaking the intertextual contract with an audience who knows the source. 1 mark: Exception: DELIBERATE, signalled contradiction as critique (counter-factual, parody, subversion) — the contradiction must be legible as a purposeful move, not an error." },
  { complexity: "complex_familiar", front: "Explain how omissions and marginalised voices in a canonical text create OPPORTUNITIES for creative responses. (2 marks)", back: "1 mark: Every omission is an invitation: silenced characters, unnarrated years and unexplained motives are spaces the original left unclaimed, where new writing can occur without displacing the source. 1 mark: Writing INTO those spaces is inherently interpretive and often political — restoring a marginalised voice repositions readers toward the whole original, exposing whose story it chose to tell." },
  { complexity: "complex_familiar", front: "What is focalisation, and why is it a more precise tool than 'point of view' when planning a creative response? (3 marks)", back: "1 mark: Focalisation is WHOSE perception filters the narrative at a given moment — who sees/knows — distinct from who narrates (voice). 1 mark: 'Point of view' conflates the two; focalisation lets you plan them separately: a third-person narrator can focalise tightly through one character's perception. 1 mark: In a response, shifting focalisation (not necessarily narrator) lets you keep the original's voice while filtering events through a different consciousness — a subtler intervention than a full perspective swap." },
  { complexity: "complex_familiar", front: "How can a writer use register and language choices to signal a character's context (class, era, culture) without stating it? (2 marks)", back: "1 mark: Vocabulary, idiom, syntax and formality encode background — clipped formal diction vs. dialect-inflected speech places a character socially and historically through HOW they speak. 1 mark: The gap between registers can carry the meaning: a character code-switching between home and institutional registers dramatises cultural navigation without exposition." },
  { complexity: "complex_familiar", front: "Why does the drafting/editing objective matter for imaginative writing specifically — what do later drafts fix that first drafts of creative work typically get wrong? (3 marks)", back: "1 mark: First drafts overtell — they explain emotions and meanings the imagery should carry; editing cuts exposition and trusts the aesthetic features. 1 mark: Consistency of voice/focalisation: drift into the writer's own register or into heads the focalisation shouldn't access is invisible while drafting, visible on reread. 1 mark: Structural economy: scenes that don't advance the response's interpretive purpose get cut — every element must serve the conversation with the original, not just the new story." },
  { complexity: "complex_unfamiliar", front: "Plan a creative response to a novel in which an unnamed servant appears in three scenes but never speaks. Specify: your form, your focalisation strategy, one aesthetic feature you will pattern, and how your piece will 'speak back' to the original's values. (6 marks)", back: "Model response: Form — a first-person monologue in three sections, each shadowing one of the servant's three scenes: the structure itself argues the servant had a continuous inner life running parallel to the plot that ignored her. Focalisation — strictly limited to the servant: the novel's protagonists appear only as she perceives them (voices through doors, demands, moods to be managed), inverting the original's distribution of interiority. Patterned aesthetic feature — hands as recurring motif: her hands working in each section (polishing, carrying, finally packing her own bag), accruing meaning from service toward self-possession; the motif carries the arc wordlessly. Speaking back — the original's value that significance belongs to the articulate and propertied is contested by making eloquence interior: her unspoken observations are sharper than the masters' dialogue, asserting that silence in the record was not absence of mind. Marking points: (1) form chosen and justified structurally; (2) focalisation strategy inverts the original's; (3) motif named with its development sketched; (4) original's value accurately identified; (5) the contestation is enacted by craft choices, not stated; (6) all four elements cohere into one interpretive claim." },
  { complexity: "complex_unfamiliar", front: "You are transforming a tragic play's final act into a short film scene. The play's meaning depends on a long dying soliloquy. Devise and justify a cinematic strategy for carrying the soliloquy's meaning without simply filming a speech. (5 marks)", back: "Model response: Strategy — distribute the soliloquy's content across cinematic channels: (1) Fragment the speech into voice-over lines placed over image sequences, keeping only the lines whose language is irreplaceable; V.O. preserves interiority, the film equivalent of soliloquy's direct access to thought. (2) Translate the speech's imagery into literal images — if the text's metaphors are of light failing, shoot the scene into a sunset that dies with him, so the visual field performs the metaphor. (3) Use sound design for the speech's rhythm: the play's pentameter decelerating can become a heartbeat/score slowing to silence. (4) Reserve one unbroken close-up for the thematic core lines — stillness as cinematic emphasis, equivalent to the actor stepping downstage. Justification: film's weakness (staged speech feels inert) is offset by its strengths (image, sound, montage); fidelity is to the soliloquy's FUNCTION — intimate access to a mind ending — not its form. Marking points: (1) V.O./fragmentation with reasoning; (2) metaphor-to-image translation; (3) sound/rhythm equivalence; (4) selective retention showing judgement about irreplaceable language; (5) explicit function-over-form fidelity principle." },
  { complexity: "complex_unfamiliar", front: "A student writes a prequel giving a novel's villain a sympathetic backstory. A peer objects: 'You've just excused everything he does in the original.' Evaluate whether explaining a character must mean excusing them, and how the prequel could be crafted to avoid this collapse. (5 marks)", back: "Model response: Explanation and excuse are separable: explanation locates causes (what made him), excuse cancels responsibility (therefore blameless) — the collapse happens when a text presents causes AS justification, usually by making the character's later choices seem inevitable. The objection has force: sympathetic backstory + reader alignment (focalisation, interiority) does tend to soften judgement; craft must actively resist the slide. Avoidance strategies: (1) include a divergence point — a moment where another character with the same wounds chooses differently, keeping his agency visible; (2) let the prequel's ending overlap the original's first cruelty, so sympathy collides with the known harm rather than fading before it; (3) keep focalisation honest — allow the reader inside his self-justifications while making their self-serving shape visible (dramatic irony as moral distance). Judgement: explanation without excuse is achievable, and is in fact the richer conversation with the original — it complicates the villain while preserving the original's moral stakes. Marking points: (1) distinguishes explain/excuse conceptually; (2) concedes the mechanism behind the peer's worry; (3)–(4) at least two concrete craft strategies; (5) reaches a justified evaluative position." },
  { complexity: "complex_unfamiliar", front: "Choose ONE structural device — non-linear timeline, frame narrative, or second-person address — and analyse how deploying it in a creative response could re-position audiences toward a familiar literary text. Include one risk of the device. (5 marks)", back: "Model response (second-person address): Writing the response as 'you' — casting the reader as the original's protagonist ('You see the letter on the table. You choose not to open it.') — converts judgement into implication: the audience can no longer evaluate the character from outside because they are being addressed as the one choosing. For a familiar text where readers have settled verdicts ('she was weak', 'he was cruel'), second person dissolves the verdict by forcing re-inhabitation of each decision point with the character's limited knowledge; hindsight is stripped away, and the original's events become live dilemmas again. This repositions the audience from judges to participants, making the response an argument that the original's character deserved understanding her context made impossible. Risk: second person can read as gimmick or coercion — readers who refuse the identification ('I would never do that') are pushed OUT of the text; sustained address also strains over length, so the device suits short, decision-centred forms. Marking points: (1) device mechanics explained; (2) linked to re-positioning of a FAMILIAR text's settled readings; (3) hindsight-stripping insight; (4) interpretive claim the device enacts; (5) genuine risk with mitigation implied." },
  { complexity: "complex_unfamiliar", front: "Two creative responses to the same colonial-era novel: one is written in the coloniser-narrator's elegant period style; the other deliberately breaks that style with fragmented, multilingual prose. Analyse what each STYLISTIC strategy claims about the original text, and which conversation is riskier. (6 marks)", back: "Model response: The period-style response works by ironic occupation: reproducing the original's register while shifting content (what the elegant voice now describes or omits) turns the style against itself — the claim is that the original's beauty was complicit, its polish a technology for making domination readable as order. Its meaning depends on precision: the pastiche must be good enough that the irony, not incompetence, is unmistakable. The fragmented multilingual response refuses the original's terms entirely: the claim is that the colonised experience cannot be carried in the coloniser's forms — syntax itself was part of the occupation — so brokenness and language-mixing perform resistance and untranslatability. Riskier: the pastiche. Its irony can be missed (read as homage) or can fail technically (read as bad imitation), and it risks re-centring the coloniser's voice even while critiquing it. The fragmentation strategy signals its politics unmistakably, though it risks inaccessibility. Judgement: the pastiche is the higher-wire act — greater reward (critique from inside) and greater failure modes. Marking points: (1) pastiche mechanism (ironic occupation); (2) its claim about complicit style; (3) fragmentation mechanism and claim; (4) both linked to the original, not free-standing; (5) risk analysis for each; (6) justified comparative judgement." },
  { complexity: "complex_unfamiliar", front: "Your creative response will be assessed on 'experimenting with aesthetic features to prompt critical and emotional responses'. Design a single scene (describe, don't write it) in which ONE aesthetic feature is engineered to produce a different emotional response on first reading and a critical realisation on reflection. (5 marks)", back: "Model response — scene design: A daughter packs her dead mother's kitchen. The engineered feature is olfactory/sensory imagery: every remembered smell (cinnamon, burnt toast, lemon soap) triggers a warm micro-memory rendered in soft, unhurried sentences. First-reading emotional effect: nostalgia and grief's sweetness — the reader is lulled into elegy. The critical turn is built by patterning: each remembered smell is attached to the mother COOKING FOR OTHERS — every memory the imagery makes beautiful is one of service. On reflection the reader realises the elegy has been cataloguing a life spent entirely in provision, and that the daughter (and reader) mistook the residue of labour for the essence of the woman: the warmth of the imagery IS the critique — love remembered through what she did for us is also how she was reduced. The feature thus runs both channels: sensory warmth (emotional) and accumulating pattern (critical), with the gap between them the scene's meaning. Marking points: (1) one feature clearly nominated; (2) first-order emotional effect engineered and plausible; (3) pattern mechanism for the critical layer; (4) the two responses genuinely differ and interact; (5) meaning located in the designed gap, not asserted." },
  { complexity: "complex_unfamiliar", front: "A marker comments on your draft response: 'Beautiful writing, but it could be about any family — where is the conversation with the original text?' Diagnose the problem and prescribe THREE specific revisions that would repair the intertextual relationship without discarding the draft. (5 marks)", back: "Model response — diagnosis: the draft succeeds as free-standing fiction but has come unmoored from the source: nothing in its situations, voices or details requires the original to exist, so it performs writing skill without performing interpretation. Revisions: (1) Anchor with transformed specifics — replant recognisable, concrete elements of the original (an object, a repeated phrase, a setting) in altered form, so readers experience the two texts simultaneously; each transformation becomes a legible interpretive move. (2) Calibrate the voice against the original's — adjust register or focalisation so the draft's style either extends or deliberately breaks the source's (and make the choice consistent), turning style itself into commentary. (3) Aim the ending at the original's gap or value — rework the final beats so they land on the specific silence, assumption or judgement in the source the response exists to answer; the ending should be unintelligible-in-full without the original. Marking points: (1) diagnosis names the missing intertextual function, not 'add more references'; (2)–(4) three distinct craft-level revisions; (5) revisions preserve the draft's strengths — repair, not rewrite." },
];

// ============================================================================
// ENGLISH — U4T2: Critical responses to literary texts (need CF 12, CU 7)
// ============================================================================
const ENG_U4T2: SeedCard[] = [
  { complexity: "complex_familiar", front: "What is 'textual integrity', and how does investigating a text's reception across different eras help establish it? (3 marks)", back: "1 mark: Textual integrity is the coherence and organic unity of a text — the way its form, language and ideas work together so it sustains rereading and multiple interpretations. 1 mark: Reception history shows whether the text keeps generating meaning in new contexts — a text continually reinterpreted (rather than merely preserved) demonstrates that its construction supports more than its original moment. 1 mark: Different eras foreground different elements (one age reads the politics, another the psychology); a text that rewards all of them has integrity beyond period appeal." },
  { complexity: "complex_familiar", front: "Distinguish an 'interpretation' from an 'opinion' in critical response writing. (2 marks)", back: "1 mark: An interpretation is a claim about the text's meaning grounded in analysable evidence — it can be tested against language, structure and pattern, and defended or revised. 1 mark: An opinion is a preference ('I found it boring') that requires no textual warrant; it reports the reader, not the text. Examiners reward interpretation because it demonstrates reasoning about construction." },
  { complexity: "complex_familiar", front: "Explain how literature has 'power to reflect AND challenge' social perspectives on issues like gender, race or class — why both verbs? (3 marks)", back: "1 mark: Reflect: texts encode their era's assumptions (casting, silences, what needs no explanation), making them evidence of past perspectives. 1 mark: Challenge: texts can also dramatise the cost of those assumptions, give voice to the marginalised, or make the familiar strange — moving audiences ahead of their context. 1 mark: The same text often does both at once (challenging class while reflecting gender assumptions), which is exactly what critical analysis must disentangle." },
  { complexity: "complex_familiar", front: "Explain the function of narrative voice as an aesthetic feature, and one way an unreliable narrator complicates interpretation. (3 marks)", back: "1 mark: Narrative voice is the personality and stance of the telling — it filters every event, sets tone, and manages the reader's distance from characters. 1 mark: An unreliable narrator forces double reading: the reader must reconstruct what happened THROUGH a distorting account, interpreting both story and teller. 1 mark: Complication: evidence for any interpretation is contaminated — the narrator's claims can't be cited at face value, so analysis must triangulate from slips, contradictions and pattern." },
  { complexity: "complex_familiar", front: "How do motif and symbol differ, and how does each accumulate meaning across a text? (3 marks)", back: "1 mark: A motif is a recurring element (image, phrase, situation) whose meaning grows from repetition and variation; a symbol is an element that stands for something beyond itself, sometimes in a single appearance. 1 mark: A motif accumulates by context: each recurrence carries the residue of previous ones, so late instances are charged with the whole pattern. 1 mark: A symbol accumulates by association: the text builds links between the object and ideas until invoking one invokes the other — motifs often harden into symbols by the end." },
  { complexity: "complex_familiar", front: "Why does an analytical essay need a 'reasoned and logical argument' rather than a sequence of correct observations? (3 marks)", back: "1 mark: Observations, however accurate, are inert until organised by a claim — the argument is what makes them evidence FOR something. 1 mark: Reasoning connects levels: technique → effect → meaning → thesis; each paragraph must complete that chain, not stop at effect. 1 mark: Logical sequencing (each point building on or complicating the last) turns the essay into a developing case; without it the marker gets a list, and lists cap the criteria for argument and synthesis." },
  { complexity: "complex_familiar", front: "Explain what it means to 'test, develop and deepen' your interpretation through others' interpretations. (3 marks)", back: "1 mark: Test — expose your reading to rival readings: if another interpretation explains textual features yours ignores, yours needs revision or defence. 1 mark: Develop — borrow lenses: a critic's angle (feminist, postcolonial, psychoanalytic) can reveal patterns you then verify independently against the text. 1 mark: Deepen — position your reading WITHIN the conversation: agreeing partially, disagreeing precisely; the final interpretation states not just what you see but why it survives the alternatives." },
  { complexity: "complex_familiar", front: "How can juxtaposition and contrast function as structural devices carrying a text's meaning? Give one example mechanism. (2 marks)", back: "1 mark: Placing scenes, characters or registers side-by-side forces comparison without commentary — the reader generates the judgement the text never states. 1 mark: Mechanism example: alternating chapters between a wealthy and a poor household during the same festival — the structure itself argues inequality; no narrator needs to say it." },
  { complexity: "complex_familiar", front: "What makes textual evidence 'integrated' rather than 'inserted' in an analytical paragraph? (2 marks)", back: "1 mark: Integrated evidence is woven into the syntax of your own analytical sentence, quoted at the phrase level, with the analysis continuing through and beyond it. 1 mark: Inserted evidence is dropped in whole ('This is shown in the quote: ...') and left to speak for itself — the quote replaces analysis instead of feeding it. Integration proves you are using the text; insertion proves you found it." },
  { complexity: "complex_familiar", front: "Explain how a text's reception can differ between its contemporaneous audience and a modern one, and what each reception reveals. (3 marks)", back: "1 mark: Contemporaneous audiences read within the text's own assumptions — what shocked or comforted them reveals the era's norms and where the text pressed against them. 1 mark: Modern audiences read across contexts: elements once unremarkable become central (the silenced wife), and once-scandalous elements become invisible. 1 mark: Comparing receptions reveals that meaning is co-produced by context — and identifies which meanings are period-bound versus which the text sustains across eras (its enduring significance)." },
  { complexity: "complex_familiar", front: "A question asks how mood is constructed in a passage. Name three distinct resources a writer uses to build mood and how each works. (3 marks)", back: "1 mark: Diction/connotation — word choices with shared emotional colouring ('grey, sagging, hushed') accumulate a dominant feeling. 1 mark: Syntax and rhythm — long suspended sentences build unease or languor; abrupt fragments create tension; the prose's pace is felt as the scene's pulse. 1 mark: Setting detail and imagery filtered through focalisation — what the perceiving character notices (shadows, exits, clocks) projects their inner state onto the world, making the reader feel it as atmosphere." },
  { complexity: "complex_familiar", front: "Why is 'the author uses techniques to engage the reader' a weak analytical claim, and what does a strong version look like? (2 marks)", back: "1 mark: It is unfalsifiable and generic — every text 'uses techniques', and 'engage' names no specific effect; it survives with any text pasted in, so it demonstrates no reading. 1 mark: Strong version names the technique, the specific effect, and the meaning at stake: 'The clipped one-line paragraphs at the reunion starve the scene of warmth, positioning readers to feel the estrangement the dialogue politely denies.'" },
  { complexity: "complex_unfamiliar", front: "A novel was celebrated on release as a patriotic war story; fifty years later critics read it as an anti-war text, citing the same battle scenes. Analyse how BOTH readings can be anchored in the same passages, and what this case shows about reception, context and textual integrity. (6 marks)", back: "Model response: The battle scenes plausibly contain both codes: heroic action, sacrifice and comradeship (the patriotic reading weights these) alongside sensory horror, futile orders and grief (the anti-war reading weights these). The original audience, reading within a culture that needed the war to mean something, foregrounded the heroic code and absorbed the horror as its price; later readers, in a context shaped by disillusioning wars, reversed the weighting — the horror becomes the point and the heroism its tragic delusion. Neither invents evidence; each is a context-driven selection from the text's genuine doubleness. The case shows reception is interpretive weighting, not fabrication: contexts function as filters that make some patterns salient. And it demonstrates textual integrity in the strong sense — the text's construction sustains contradictory serious readings across eras, which is why it remains studied while univocal propaganda from the same year does not. It may also suggest the doubleness was the author's design: writing horror INTO celebration was perhaps the only publishable form of dissent. Marking points: (1) locates both codes in the same scenes; (2) explains the original weighting via context; (3) explains the later reversal via context; (4) frames reception as selection, not invention; (5) draws the textual-integrity conclusion; (6) considers designed ambiguity." },
  { complexity: "complex_unfamiliar", front: "You are writing an analytical essay arguing an interpretation you know contradicts the most common reading of a studied text. Devise your argumentative strategy: how you will use the dominant reading, sequence your evidence, and manage the examiner's likely resistance. (5 marks)", back: "Model response: Use the dominant reading as the frame, not the enemy: open by stating it fairly and identifying the textual features it explains well — this proves my disagreement is informed, not ignorant. Sequence: (1) locate the anomaly — the scenes, lines or structural choices the dominant reading cannot account for or must dismiss as flaws; anomalies are the wedge. (2) Introduce my interpretation as the account that makes the anomalies purposeful, then re-read the dominant reading's OWN best evidence through my lens, showing my claim doesn't lose that evidence but reframes it. (3) Concede the limit: specify what my reading leaves open, converting a weakness into scholarly precision. Managing resistance: signpost the argumentative moves explicitly ('the standard reading accounts for X but stumbles on Y'), keep the tone of extension rather than demolition, and anchor every contentious claim at phrase-level in the text — resistance to a bold thesis falls when each step is small and evidenced. Marking points: (1) dominant reading deployed as frame; (2) anomaly-first sequencing; (3) re-reading of rival evidence rather than avoidance; (4) explicit concession; (5) tone/signposting strategy for a sceptical assessor." },
  { complexity: "complex_unfamiliar", front: "Two critics disagree about a female character who destroys her family's fortune: Critic A (1960s) calls her 'the novel's moral failure'; Critic B (2010s) calls her 'the novel's only free agent'. Using the concepts of cultural assumptions and privileged/marginalised perspectives, analyse what each verdict reveals about its critic's context — then state what a third reading might notice that both miss. (6 marks)", back: "Model response: Critic A's verdict assumes the family's continuity is the moral centre — a framework in which female virtue equals custodianship of home and fortune; judging her a 'failure' measures her against duties the critic's context naturalised, revealing an era reading through obligation. Critic B inverts the frame: reading through autonomy, destruction becomes self-assertion — the only action in the novel not scripted by men. This reveals a context that prizes individual agency and reads institutions as constraints; but 'only free agent' romanticises harm, marginalising the perspectives of those (children, servants) her freedom cost — B repeats A's error in mirror image, fitting the character to the critic's values. A third reading might notice the text's OWN distribution of perspective: whose focalisation frames her acts, who is given interiority in the aftermath, and whether the novel's structure (e.g. ending on the ruined household or on her departure) privileges cost or liberation. That is, both critics argued about her; the text's construction — its choices about seeing — may itself take a side neither examined. Marking points: (1) A's assumptions unpacked; (2) B's assumptions unpacked; (3) both framed as context-driven weighting; (4) B's marginalised-perspectives blind spot; (5) third reading turns to construction/focalisation; (6) sustained use of the named concepts rather than plot debate." },
  { complexity: "complex_unfamiliar", front: "An exam passage is the final page of a novel you have studied: a quiet domestic scene with no plot resolution. Devise a strategy for producing a full analytical response to 'How does this ending contribute to the meaning of the whole text?' when 'nothing happens' in the passage. (5 marks)", back: "Model response: Reframe quietness as choice: an ending is the text's final act of emphasis, so a refusal of resolution IS the resolution — the strategy is to analyse what the ending declines and what it substitutes. Steps: (1) map the passage against the novel's established patterns — which motifs recur here in final position (the table set for fewer, the window now open) and how their last variation completes or breaks the pattern; endings retroactively fix motif meanings. (2) Analyse the aesthetic register: pace, sentence rhythm and imagery of the 'quiet' — stillness after turbulence reads as peace, exhaustion or erasure depending on construction; name which and prove it at phrase level. (3) Address structure: what conventional endings (marriage, death, judgement) the genre made available and the text refused — the refusal positions the reader to locate meaning in the ordinary, or denies them the comfort of closure. (4) Synthesise: state what the whole text MEANS differently because it ends here rather than at the climax. Marking points: (1) refusal-as-choice reframing; (2) motif-completion analysis; (3) register/rhythm analysis of quietness; (4) genre-expectation contrast; (5) whole-text synthesis, not passage description." },
  { complexity: "complex_unfamiliar", front: "A director's film adaptation of a studied novel cuts its frame narrative (an old narrator recalling events) and tells the story chronologically. Critics say the film is 'faithful to the plot but not the meaning'. Analyse what meanings a frame narrative constructs and evaluate the critics' claim. (5 marks)", back: "Model response: A frame narrative constructs: (1) mediation — every event arrives pre-interpreted by the recalling narrator, so the story is also a study of memory, selection and self-justification; (2) temporal irony — the frame's hindsight lets endings haunt beginnings, generating elegy or dread the events alone don't carry; (3) an epistemology — the novel is 'an account', inviting scrutiny of the teller's reliability and motives. Cutting the frame keeps the events but deletes this second story: chronological telling renders events immediate and objective, so the film presents as fact what the novel presented as remembered construction. The critics' claim is therefore substantially right — plot fidelity preserved the WHAT while the frame carried the ABOUT (memory, unreliability, loss) — though 'not the meaning' overstates: film can rebuild mediation with voice-over, framing devices or unreliable focalisation, so the loss was a directorial choice, not the medium's necessity. Evaluation: faithful adaptation should be judged against the source's construction of meaning, not its event sequence. Marking points: (1)–(3) three distinct frame functions; (4) analysis of what chronology substitutes; (5) nuanced verdict acknowledging cinematic equivalents." },
  { complexity: "complex_unfamiliar", front: "In a timed external exam, you realise halfway through your analytical response that your thesis is drifting — paragraphs are accurate but no longer arguing one claim. Prescribe an in-exam recovery strategy and justify each step against the assessment demand for a sustained, cogent argument. (5 marks)", back: "Model response: (1) Stop and restate — take 60 seconds to write, in one sentence on the plan page, the claim my best paragraphs actually support; drift usually means the real thesis emerged mid-essay and is better than the opener. (2) Steer, don't rewrite — no time to redraft; instead open the next paragraph with a synthesising topic sentence that explicitly gathers the prior points under the real claim ('Together, the narration and the motif suggest that...'), converting apparent drift into staged development. (3) Discipline remaining paragraphs — before each, ask what it adds to THE claim; cut planned material, however good, that doesn't. (4) Rebuild in the conclusion — restate the refined thesis as the destination the essay has been arguing toward, naming how each strand contributed; a strong synthesising conclusion retroactively confers cohesion markers reward. Justification: assessors reward the argument the essay actually sustains; recovery therefore optimises the visible chain (claim → linked paragraphs → synthesis) rather than cosmetic consistency with a flawed opening. Marking points: (1) diagnostic restatement step; (2) synthesising steer rather than rewrite; (3) forward discipline test; (4) conclusion as retro-cohesion; (5) every step justified against argument/synthesis criteria, with exam-time realism." },
  { complexity: "complex_unfamiliar", front: "'Great literature transcends its context.' Using ONE studied text, mount a case FOR this claim and a case AGAINST it, then argue for the most defensible position on what actually 'travels' when a text endures. (6 marks)", back: "Model response: FOR — the text keeps producing meaning for readers who share none of its context: its handling of grief, power or desire is recognised across centuries, and its formal design (structure, imagery) rewards analysis independent of period knowledge; endurance itself is evidence something exceeds the moment. AGAINST — 'transcendence' conceals labour: the text survives because institutions (canons, syllabuses, adaptations) continually re-translate it; each era reads a different text (as reception history shows), and its 'universal' themes are abstractions we extract by ignoring context-bound content — often the parts now uncomfortable. What travels is not a fixed meaning but a generative capacity: a construction rich and coherent enough (textual integrity) to support re-interpretation under new assumptions. So the defensible position is neither transcendence (meanings fixed above history) nor pure relativism (nothing but context): texts endure when their formal organisation keeps offering new contexts something to work with — the text supplies the score, each era performs it. 'Transcends its context' is thus half-true: it escapes captivity to its ORIGINAL context precisely by being re-contextualisable, never context-free. Marking points: (1) FOR case with formal + reception evidence; (2) AGAINST case naming institutional mediation; (3) the different-text-each-era insight; (4) synthesis via generative capacity/textual integrity; (5) the score/performance (or equivalent) reconciliation; (6) judgement stated and defended, not both-sides-ism." },
];

// ============================================================================
// PE — U3T1: Tactical awareness (need CF 5, CU 4)
// ============================================================================
const PE_U3T1: SeedCard[] = [
  { complexity: "complex_familiar", front: "Contrast the cognitive systems approach and the dynamic systems approach to motor learning. (3 marks)", back: "1 mark: Cognitive approach — hierarchical control: higher centres pass commands to lower centres, producing linear, planned changes in movement; focuses on decision-making and executing stored plans. 1 mark: Dynamic systems approach — movement emerges/self-organises from the interaction of learner, task and environment; changes are non-linear and unpredictable, with no hierarchical command structure. 1 mark: Key contrast: cognitive = movement is computed then executed; dynamic = movement emerges from constraints in the moment, better matching the complexity of authentic game play." },
  { complexity: "complex_familiar", front: "Explain perception–action coupling and the role of affordances, using a touch football example. (3 marks)", back: "1 mark: Perception–action coupling is the direct link between interpreting environmental information and a specific action — perception drives action, and acting reveals new information (action drives perception). 1 mark: An affordance is an opportunity for action offered by the environment/task RELATIVE to the learner's abilities — a gap between defenders affords running through it only if the player has the speed. 1 mark: As skill develops the learner becomes more attuned to affordances — an experienced touch player perceives a closing gap earlier and couples it to a dart or a pass without deliberate calculation." },
  { complexity: "complex_familiar", front: "Explain how each of the three constraint categories can be manipulated in a constraints-led training session. (3 marks)", back: "1 mark: Task constraints — modify rules, scoring, equipment or numbers (e.g. two-touch scoring zones, smaller balls) to channel players toward discovering target movement strategies. 1 mark: Learner/individual constraints — can't be 'set' in a session but are considered: grouping by or against physical/skill differences so players adapt to teammates' and opponents' strengths and limitations. 1 mark: Environmental constraints — vary playing area dimensions, surface or conditions (narrow the field to force short passing) so solutions self-organise rather than being instructed." },
  { complexity: "complex_familiar", front: "Explain the four principles of decision-making in physical activity and why they form a cycle. (3 marks)", back: "1 mark: Reading play (scanning for information) → recognising information and responding (selecting the meaningful cues and choosing) → reacting to implement movement (executing) → recovering with appropriate movements (repositioning on/off the ball). 1 mark: Each phase feeds the next: recovery position determines what can be read next, so the four form a continuous loop rather than a one-off sequence. 1 mark: Breakdowns are diagnosable per phase — e.g. a player who reads play well but reacts late has a coupling/execution problem, not a perception problem, which changes the training fix." },
  { complexity: "complex_familiar", front: "Why must a devised tactical strategy be justified with BOTH primary and secondary data? Give an example of each doing different work. (3 marks)", back: "1 mark: Primary data (your own performance: GPS traces, video coding, success rates in authentic games) establishes the personal/team problem the strategy addresses and later whether it worked. 1 mark: Secondary data (published research, expert analysis, professional match statistics) establishes that the proposed principle is credible beyond your sample — e.g. research on creating space supporting a width-based attack. 1 mark: Together they prevent the two failure modes: strategy based only on theory (may not fit YOUR constraints) or only on personal impressions (may misread the cause)." },
  { complexity: "complex_unfamiliar", front: "In your 6-week touch football unit, video coding shows your attacking success rate drops from 62% to 31% when the defence rushes quickly. Devise a tactical strategy using the constraints-led approach and TWO principles of play, and describe the primary data you would gather to evaluate it. (6 marks)", back: "Model response: Diagnosis — the rushing defence compresses time between reading play and reacting; my current strategy needs affordances that exist BEFORE the rush arrives. Strategy: principle 1 — creating and exploiting space: pre-call switch plays that move the ball away from the rush side, using width to stretch the defensive line so gaps open laterally rather than ahead. Principle 2 — setting up attack: establish a quick-ruck structure (acting-half runs, dump-and-support) that attacks during defensive re-set, before the rush can launch. Constraints-led development: train via task manipulation — defenders instructed to rush every play in training games, field narrowed then progressively widened, so attackers self-organise solutions under the exact constraint that beats us. Evaluation data: re-code the same metrics in authentic games (attack success % vs rushing defence, time-to-pass after ruck, line breaks by field zone) across three matches, comparing against the 31% baseline; supplement with heat maps showing whether width is actually being used. Marking points: (1) diagnosis links data to a tactical cause; (2) two DISTINCT principles of play applied; (3) constraints-led logic (manipulated task, emergent solutions) not drill prescription; (4) strategy targets the specific rushing constraint; (5) evaluation metrics match the original data for comparability; (6) coherent line from data → strategy → re-measurement." },
  { complexity: "complex_unfamiliar", front: "A teammate argues: 'Just tell us the set plays — all this small-sided constraint game stuff wastes time.' Using dynamic systems theory and the ecological model, justify the constraints-led approach over direct instruction for developing tactical awareness. (5 marks)", back: "Model response: Set plays assume the cognitive model — movement as stored commands retrieved on cue — but authentic game play is a complex dynamic system: defenders, space and time never reproduce the drilled configuration, so a play memorised as a fixed sequence breaks when the environment varies. Dynamic systems theory holds that movement self-organises under interacting constraints; training through manipulated small-sided games exposes players to constantly varying configurations, so they develop stable-but-flexible solutions rather than one brittle script. The ecological model adds attunement: tactical awareness is fundamentally perceiving affordances (the gap, the overlap) and coupling them to action; that perception–action link only sharpens through repeated exposure to genuine information from live play — a walked-through set play contains no perceptual information to attune to. Concession: set plays retain value for restart situations where the configuration IS fixed (taps, scrums). But for open play, the constraint games aren't a detour from tactical learning — they are the mechanism of it. Marking points: (1) identifies set plays with the cognitive model; (2) applies self-organisation under constraints; (3) applies attunement/affordances to tactical awareness; (4) explains why live perceptual information can't be replaced by instruction; (5) balanced concession showing evaluation, not advocacy." },
  { complexity: "complex_unfamiliar", front: "Design how you would use 'off-the-ball' movement data to evaluate a midfielder whose on-the-ball statistics are excellent but whose team performs better when she is substituted. Use body and movement concepts as your criteria. (5 marks)", back: "Model response: The paradox suggests her contribution problem is off the ball, invisible to on-ball stats. Data design: video-code her movement when NOT in possession across two matches, categorised by body and movement concepts — Space awareness: her positioning relative to team structure (does she drift into teammates' channels, collapsing width? does she move INTO space or occupy it early and stagnate?); Relationships: her interactions with teammates and opponents off the ball (does she drag defenders away to create space for others, or bring her marker into the play space? does she offer support angles for the ball-carrier?); Quality of movement: efficiency of her repositioning (recovery runs after turnovers, work-rate symmetry attacking vs defending); Body awareness: movement selection off the ball (checking runs, blind-side leads) versus standing rest. Evaluation: compare her off-ball metrics with the replacement's — if the sub creates more space via decoy runs and better defensive recovery, the team-performance gap is explained: her on-ball excellence is bought at the cost of off-ball contribution. Marking points: (1) recognises the paradox implies off-ball causes; (2)–(4) at least three body/movement concepts operationalised into observable metrics; (5) comparison design (her vs substitute) that can actually answer the question." },
  { complexity: "complex_unfamiliar", front: "Your devised strategy worked in training games but failed in the real match. Using the constraints framework, analyse three plausible reasons for the transfer failure and what each implies about how you should modify the strategy or the training. (5 marks)", back: "Model response: Reason 1 — environmental constraints differed: training occurred on a smaller familiar field without crowd noise or weather; the match environment changed the information available (harder to hear calls, different surface affecting cuts). Implication: rep the strategy under varied environments — different venues, imposed noise, wet-ball sessions — so solutions stay stable across environmental variation. Reason 2 — task constraints in training misrepresented the match: if training games used rushed defenders who rushed EVERY play, attackers attuned to a predictable constraint; real defenders rushed selectively, breaking the learned coupling. Implication: train with variable, probabilistic defensive behaviour so perception (reading WHETHER the rush comes) is trained, not just the response. Reason 3 — learner constraints shifted: match arousal/pressure is itself an individual constraint; under anxiety, attention narrows and players revert to older stable movement states. Implication: progressively add consequence and pressure to training (scores, audiences, fatigue) so the new strategy becomes the stable state under stress. Marking points: (1)–(3) three reasons each correctly located in a constraint category; (4) each with a matched, specific modification; (5) analysis shows transfer = constraint-fidelity between training and performance environments." },
];

// ============================================================================
// PE — U3T2: Ethics and integrity (need CF 9, CU 5)
// ============================================================================
const PE_U3T2: SeedCard[] = [
  { complexity: "complex_familiar", front: "Distinguish ethics, fair play and integrity as used in the PE syllabus. (3 marks)", back: "1 mark: Ethics — the set of norms and values through which we realise acceptable behaviour and judgements of right and wrong; a person's ethical system forms their character. 1 mark: Fair play — the enacted attitudes/behaviours: observing rules, fair competition and equality, respect, team spirit, eliminating exploitation (violence, cheating, drugs), honouring written AND unwritten rules. 1 mark: Integrity — the outcome state: fair and honest performances unaffected by illegitimate enhancement or external interests, plus positive stakeholder engagement that maintains community confidence in the activity." },
  { complexity: "complex_familiar", front: "Outline the five steps of the ethical decision-making framework. (3 marks)", back: "1 mark: (1) Identify the ethical dilemma — the problem and the tension between the organisation's/player's values. (2) Find information — relevant facts, stakeholders with an important stake in the outcome, strategies used for similar problems. 1 mark: (3) Evaluate alternatives — which strategies produce most good/least harm, best respect rights, treat people equally or proportionately, best serve the community, lead players to act with integrity. 1 mark: (4) Devise strategies — a course of action to improve integrity. (5) Reflect on the outcome — determine the strategy's effectiveness for all stakeholders." },
  { complexity: "complex_familiar", front: "Explain the difference between the 'most good/least harm' test and the 'rights' test when evaluating alternatives in an ethical dilemma. (2 marks)", back: "1 mark: Most good/least harm is consequentialist — it weighs total outcomes across everyone affected, accepting costs to some if the aggregate benefit is larger. 1 mark: The rights test is non-negotiable per person — an option that violates an individual's legitimate rights fails even if it maximises overall good; the framework uses both so majority benefit can't simply override individuals." },
  { complexity: "complex_familiar", front: "Explain how codes of behaviour, rules and policies support ethical behaviour in class, school and community sport — and their limitation. (3 marks)", back: "1 mark: They make expectations explicit and universal (what counts as abuse, selection criteria, risk procedures), removing 'I didn't know' and enabling consistent enforcement. 1 mark: They protect the vulnerable proactively — risk assessments and codes of conduct anticipate harms rather than reacting to them, and give stakeholders a mechanism to report breaches. 1 mark: Limitation: codes govern compliance, not character — they cover written rules, while fair play also depends on unwritten norms (honesty when unobserved, spirit of the game) that documents cannot enforce." },
  { complexity: "complex_familiar", front: "Explain two ways globalisation and media coverage have influenced ethical values and behaviours in sport. (2 marks)", back: "1 mark: Amplified stakes: global audiences and sponsorship make winning enormously lucrative, strengthening incentives for doping, match-fixing and gamesmanship — commercial pressure reshapes what behaviour feels 'worth it'. 1 mark: Amplified scrutiny and norm-transfer: constant coverage exposes misconduct instantly and spreads behavioural norms (positive and negative — sportsmanship moments AND simulation/diving) across cultures, so local values are increasingly shaped by global sporting media." },
  { complexity: "complex_familiar", front: "Identify the roles of peers, family, coaches and school/community in developing personal values and ethical behaviour in physical activity. (3 marks)", back: "1 mark: Peers — normalise behaviour: what teammates laugh at, celebrate or tolerate (sledging, diving) becomes the operating standard regardless of official rules. 1 mark: Family and coaches — model and reward: children absorb what parents applaud from the sideline and what coaches actually select for (a coach who picks the diver teaches diving). 1 mark: School/community — institutionalise values: codes of conduct, how breaches are handled, which behaviours are publicly honoured — the structures signal what the community genuinely values versus what it merely states." },
  { complexity: "complex_familiar", front: "Why is an ethics strategy required to identify 'audience, context and outcome'? Explain with a brief example. (3 marks)", back: "1 mark: Audience — a strategy works by changing specific people's behaviour; 'reduce sledging' means nothing until you name whose behaviour (players, parents, spectators) it targets, because levers differ per group. 1 mark: Context — class, school and community settings have different authority structures and stakes; a strategy enforceable by a teacher in class may be unenforceable at community level where participation is voluntary. 1 mark: Outcome — a defined, observable end-state (e.g. zero send-offs for dissent this season) makes the strategy evaluable; example: a parent-behaviour strategy targeting sideline abuse (audience: parents; context: junior club fixtures; outcome: complaints reduced by half by season end)." },
  { complexity: "complex_familiar", front: "Describe how an ethics strategy could NEGATIVELY influence integrity, with one mechanism. (2 marks)", back: "1 mark: A strategy can backfire when it targets appearances over causes — e.g. harsh automatic penalties for reporting doping incidents can drive concealment, reducing detected cases while the underlying behaviour continues (integrity looks better, is worse). 1 mark: Mechanism: incentive distortion — stakeholders optimise against the strategy's measure (avoid being caught, shift blame) rather than toward the value it was meant to protect." },
  { complexity: "complex_familiar", front: "Why does the framework require identifying ALL stakeholders with 'an important stake in the outcome' before evaluating alternatives? (2 marks)", back: "1 mark: Ethical dilemmas look different per stakeholder — an option that is 'most good' for the team (playing the concussed star) may be gravely harmful for the individual; missing a stakeholder biases the evaluation toward whoever is visible. 1 mark: Stakeholder mapping also surfaces whose rights are at risk and who must be part of implementation — a strategy no key stakeholder accepts (e.g. coaches) will fail at the reflection step regardless of its logic." },
  { complexity: "complex_unfamiliar", front: "Your school's open touch team can win the grand final by repeatedly targeting the opposition's weakest player — a Year 8 filling in due to injuries. It breaks no rule. Apply the full ethical decision-making framework to this dilemma, reaching a justified course of action. (6 marks)", back: "Model response: (1) Identify: the dilemma is winning-within-rules vs. fair competition and care for a vulnerable participant — tension between the team's value of success and the school's values of respect and equality. (2) Find information: facts — legal tactic, significant skill/age gap, risk of humiliation or discouragement from sport; stakeholders — the Year 8 player, both teams, coaches, schools, spectators; similar situations — mercy rules and rotation policies exist precisely for mismatches. (3) Evaluate alternatives: (a) target relentlessly — most 'good' for our result but concentrates harm on the least powerful stakeholder, fails the rights/equality test, and models exploitation; (b) never attack her channel — patronising and artificial, arguably disrespects her as a competitor; (c) play normal structured attack, exploiting space wherever it appears without singling her out repeatedly — preserves genuine competition, distributes pressure, respects all parties. (4) Devise: adopt (c) with a captain's brief before the game; communicate the standard ('we attack space, not people'). (5) Reflect: post-game, review whether the outcome upheld integrity — result achieved through performance, opposition's experience preserved, our players' character reinforced. Judgement: (c), because fair play includes unwritten rules — eliminating exploitation in the effort to win is definitional, and a win manufactured from a child's vulnerability damages the very confidence in sport that integrity names. Marking points: (1) dilemma + value tension; (2) facts and full stakeholder set; (3) ≥3 alternatives tested against the framework's criteria; (4) concrete strategy; (5) reflection step included; (6) justified judgement invoking fair play/integrity concepts." },
  { complexity: "complex_unfamiliar", front: "Survey data at your school shows 40% of senior students avoid PE participation, with girls citing 'being watched and judged' at triple the rate of boys. Devise an ethics strategy for this engagement dilemma, justify it with the data, and design its evaluation. (6 marks)", back: "Model response: Identify: the dilemma is equity of engagement — the current PE environment distributes psychological safety unequally, tension between 'PE as performance/competition' values and inclusion values. Strategy (audience/context/outcome): audience — senior PE classes and staff; context — school PE lessons; outcome — reduce avoidance to under 20% and halve the gender gap within two terms. Actions: restructure lessons to offer parallel participation formats (competitive stream and a games/fitness stream chosen weekly), introduce single-gender option blocks for activities the data flags as most judgement-exposed, and set class norms co-written with students banning commentary on others' performance. Justification from data: avoidance is concentrated where perceived surveillance is highest, so the levers reduce audience exposure (streaming, option blocks) and delegitimise judgement (norms) — targeting the cited cause, not attendance itself. Secondary data on choice-based PE supports autonomy as an engagement driver. Evaluation design: re-run the same survey (same items, for comparability) at term's end plus participation records per stream; disaggregate by gender; reflect with a student focus group on whether integrity of the changes held (were streams stigmatised?). Adjust: if the competitive stream became high-status and the other stigmatised, the strategy shifted the harm rather than removing it — modify. Marking points: (1) dilemma framed in ethics/engagement terms; (2) strategy specifies audience, context, measurable outcome; (3) ≥2 concrete actions; (4) justification explicitly links actions to the cited data mechanism; (5) evaluation re-uses baseline measures; (6) anticipates a backfire mode and a modification path." },
  { complexity: "complex_unfamiliar", front: "A talented teammate confides they are using a banned substance obtained legally overseas, arguing: 'It just corrects my natural disadvantage — that's FAIRER.' Evaluate their argument using the concepts of fair play, integrity, and the level playing field, then state what the ethical decision-making framework says about your own obligations. (5 marks)", back: "Model response: The argument fails on three grounds. Fair competition: sport's premise is comparing performances produced under shared constraints — the rules define WHICH natural inequalities the contest measures (talent, training response); unilaterally re-drawing that line isn't correcting unfairness, it's substituting a private definition of fair for the agreed one. Integrity: integrity requires performances 'unaffected by illegitimate enhancements' — legality of purchase is irrelevant; legitimacy is defined by the sport's rules, and concealed enhancement converts every result into deception of opponents who kept the agreement. Level playing field: the argument proves too much — every athlete has some 'natural disadvantage', so the principle licenses universal doping, which restores the original inequality at higher health cost and destroys community confidence. My obligations via the framework: identify the dilemma (loyalty to a friend vs. duty to fair competition and their health); find information (substance risks, reporting channels, consequences); evaluate alternatives — silence makes me complicit and fails other stakeholders (clean teammates, opponents); best option is urging them to stop and disclose, with escalation to appropriate confidential channels if refused, respecting both their welfare and the contest's integrity. Marking points: (1) fair-competition rebuttal (agreed constraints); (2) integrity/legitimacy distinction from legality; (3) universalisation problem; (4) framework applied to the bystander's duty; (5) a defensible, escalating course of action rather than a binary." },
  { complexity: "complex_unfamiliar", front: "A community club's star junior coach produces winning teams but players quietly quit at unusual rates, citing fear of his criticism. The committee says: 'No code-of-conduct breach has been reported.' Analyse this situation as an integrity problem using the concepts of stakeholder engagement and written vs unwritten rules, and devise the first three steps you would take. (5 marks)", back: "Model response: Integrity in the syllabus sense includes 'positive engagement by athletes... which enhances the standing of the activity' — a coach whose methods drive silent attrition is an integrity failure even with zero formal breaches, because the harm shows up in engagement data, not incident reports. The committee's defence confuses written rules (the code's explicit prohibitions) with the unwritten rules of fair play (respect, care, sport as a positive pursuit): a code catalogues reportable acts; sustained belittling can stay under every clause while destroying the experience the code exists to protect. Fear also suppresses reporting — using the absence of reports as evidence is circular when the alleged harm is precisely what stops reports. First three steps (framework-aligned): (1) Find information — gather primary data independent of the reporting channel: structured exit interviews with departed players/parents, retention statistics benchmarked against other squads; (2) identify stakeholders — players (current and departed), parents, the coach (who has rights too, including fairness and support to change), committee, club reputation; (3) evaluate alternatives before acting — mediated feedback and coach-education with monitored retention, versus removal — testing each against most-good/least-harm, rights, and community confidence. Marking points: (1) engagement-based definition of integrity applied; (2) written/unwritten rules distinction; (3) circularity of 'no reports' identified; (4) first steps map to the framework's find-information stage with real data sources; (5) coach's rights acknowledged — evaluation, not verdict." },
  { complexity: "complex_unfamiliar", front: "Prize money at your regional championships is double for the men's draw. Organisers argue men's events 'sell more tickets'. Using the ethical decision-making framework's evaluation criteria (most good/least harm, rights, equality/proportionality, community, integrity), analyse whether the differential is defensible and devise a strategy an athlete group could realistically implement. (6 marks)", back: "Model response: Most good/least harm — the revenue argument counts only commercial good; harms include devaluing women's performances, discouraging participation, and reputational damage as norms shift; aggregate harm plausibly exceeds the ticketing gain. Rights — athletes have a defensible claim to equal recognition for equal competitive achievement within the same event; paying by audience makes worth contingent on historical exposure the organisers themselves control (scheduling, promotion). Equality vs proportionality — organisers invoke proportionality (pay tracks revenue); but revenue is endogenous: decades of unequal promotion built the audience gap, so proportionality-to-revenue launders past inequality into future pay. Community — junior girls watching learn their ceiling; community confidence in sport as an ethical pursuit erodes. Integrity — external commercial interests are shaping outcomes and engagement, the definition of an integrity risk. Verdict: not defensible; at minimum the club must move toward parity with a published timeline. Athlete strategy (audience: organisers/sponsors; context: regional championships; outcome: equal prize money within two seasons): collect and publish the data (attendance, viewership, sponsorship attribution) — often weaker than claimed; coordinate men's and women's draws jointly (men's cooperation removes the divide-and-rule risk); propose a sponsor-funded parity pool, giving organisers a face-saving mechanism; escalate publicly only if refused. Evaluate: track the outcome and stakeholder responses, reflect, modify. Marking points: (1)–(3) at least four framework criteria genuinely applied; (4) endogeneity/proportionality insight; (5) realistic multi-step strategy with audience-context-outcome; (6) evaluation/reflection step present." },
];

// ============================================================================
// PE — U4T1: Energy, fitness and training (need CF 9, CU 5)
// ============================================================================
const PE_U4T1: SeedCard[] = [
  { complexity: "complex_familiar", front: "Explain the interplay of the three energy systems during a 70-minute touch football game, referencing intensity and duration. (3 marks)", back: "1 mark: All three systems contribute simultaneously from the start — interplay, not sequence; their RATIOS shift with intensity and duration. 1 mark: High-intensity efforts (sprints to score, defensive rushes, ~0–10 s) are dominated by ATP–PC; repeated efforts with short recovery push contribution to the lactic acid system (high intensity, moderate duration) as PC stores can't fully replenish. 1 mark: Between efforts and across the full 70 minutes, the aerobic system dominates — resynthesising ATP for sub-maximal work (positioning, jogging) and driving recovery (PC restoration, lactate clearance), which is why aerobic capacity underpins repeat-sprint performance." },
  { complexity: "complex_familiar", front: "Explain how work:rest ratios from game analysis are used to make training specific to an activity's energy demands. (3 marks)", back: "1 mark: Coding a game gives the typical W:R ratio (e.g. 1:4 — 5 s sprint, 20 s cruise/rest), which identifies the dominant energy system and recovery pattern of actual performance. 1 mark: Training specificity: interval sets are built to mirror that ratio (and its intensity/duration), stressing the same system the game stresses — e.g. 1:4 sprint intervals develop ATP–PC replenishment for repeat efforts. 1 mark: Manipulating the ratio shifts the target: shortening rests (1:2) trains lactic tolerance; lengthening work periods trains aerobic capacity — the ratio is the design lever." },
  { complexity: "complex_familiar", front: "Distinguish progressive overload from specificity, and explain what happens to a training program when either is ignored. (3 marks)", back: "1 mark: Progressive overload — planned, gradual increases in training load so adaptation continues; specificity — training must match the energy systems, movements and fitness components of the target activity. 1 mark: Ignore overload → plateau: the body fully adapts to a static load and fitness stops improving (or reverses via detraining if load falls). 1 mark: Ignore specificity → misdirected adaptation: fitness improves on the trained quality but transfers poorly (a touch player doing only 5 km runs builds aerobic capacity while repeat-sprint speed and agility — the game's actual demands — stagnate)." },
  { complexity: "complex_familiar", front: "Explain the physiological responses to aerobic training that increase VO2 max, referencing stroke volume and cardiac output. (3 marks)", back: "1 mark: Aerobic training enlarges/strengthens the left ventricle → stroke volume (blood per beat) rises; since cardiac output = SV × HR, more oxygenated blood is delivered per minute at any effort. 1 mark: Peripheral adaptations — increased capillarisation and mitochondrial density in trained muscle — raise oxygen extraction and utilisation. 1 mark: VO2 max (maximal oxygen uptake/use) rises because both delivery (central) and utilisation (peripheral) improve; resting HR falls as the same output needs fewer beats." },
  { complexity: "complex_familiar", front: "Compare HIIT and continuous training as methods: target adaptations, energy systems and one trade-off each. (3 marks)", back: "1 mark: HIIT — repeated high-intensity work with manipulated rest; targets the anaerobic systems AND aerobic power (working near VO2 max), improves lactate threshold and repeat-effort capacity; trade-off: high injury/fatigue cost, needs recovery management. 1 mark: Continuous — sustained sub-maximal work ≥20 min; develops aerobic capacity efficiently and safely with low technical demand; trade-off: poor specificity for intermittent sports (no repeat-sprint or lactic stress). 1 mark: Selection logic: match to game analysis — intermittent, high-intensity sports justify HIIT emphasis; endurance events justify continuous volume; most programs blend them across a mesocycle." },
  { complexity: "complex_familiar", front: "Explain how a mesocycle, microcycles and training sessions nest inside an annual plan (periodisation), and the purpose of the phases. (3 marks)", back: "1 mark: The annual plan divides the year into phases — preparatory (build base fitness), pre-competition (sharpen specific fitness/speed), competition (maintain and peak), transition (active recovery) — sequencing adaptation so peak fitness lands at the right time. 1 mark: A mesocycle is a 4–6 week block within a phase with one training focus (e.g. aerobic base); a microcycle is ~1 week structuring that focus into a pattern of load and recovery; a session is the organised activities of one timeframe. 1 mark: The nesting lets load be periodised at every scale — hard/easy sessions within a microcycle, loading/deloading weeks within a mesocycle — so overload accumulates without overtraining." },
  { complexity: "complex_familiar", front: "Explain the RAMP warm-up structure and the physiological purpose of each element. (2 marks)", back: "1 mark: Raise — elevate body temperature, heart rate, respiration and joint viscosity via gentle cardio; Activate — switch on the key muscle groups for the session (e.g. glute activation). 1 mark: Mobilise — take relevant joints through range of motion; Prepare — dynamic stretching and movement rehearsal at increasing intensity so the neuromuscular system is primed for the session's specific demands." },
  { complexity: "complex_familiar", front: "Why is recovery described as a training principle rather than an absence of training? Include active recovery and reversibility in your answer. (3 marks)", back: "1 mark: Adaptation occurs DURING recovery — training provides the stimulus, recovery is when the body rebuilds above baseline (supercompensation); without it, accumulated fatigue blocks adaptation and risks overtraining/injury. 1 mark: Active recovery (light movement) clears metabolic by-products faster than passive rest and maintains readiness for competition or the next session. 1 mark: But recovery must be dosed: excessive rest triggers reversibility — adaptations reverse when training load ceases — so programs plan recovery (tapering, transition phases) rather than just stopping." },
  { complexity: "complex_familiar", front: "A netball centre's fitness testing shows high aerobic capacity but poor repeated-sprint ability and agility. Which components of fitness should her training prioritise and why, referencing position demands? (2 marks)", back: "1 mark: Prioritise speed, power and agility with repeat-sprint conditioning (ATP–PC/lactic emphasis): a centre's game is repeated short sprints, cuts and rapid changes of direction — her aerobic base is already sufficient to support recovery between efforts. 1 mark: Specificity and individuality principles: training targets HER limiting components in HER position's movement patterns (court-length repeat sprints, reactive agility), rather than adding more of an already-strong quality." },
  { complexity: "complex_unfamiliar", front: "Design a one-week microcycle (5 sessions) for a touch football wing in the pre-competition phase, whose game analysis shows W:R of ~1:4, dominant ATP–PC demand, and whose testing shows weak speed but strong aerobic capacity. Justify each session against training principles. (6 marks)", back: "Model response: Mon — speed/power: resistance training (lower-body strength + power, e.g. squats/plyometrics); justification: individuality (targets tested weakness) and specificity (speed is ATP–PC-driven, force production underpins it). Tue — repeat-sprint intervals at game W:R: 3 sets of 6 × 5 s maximal sprints, 20 s active recovery (1:4); justification: specificity to coded game demands, trains PC replenishment. Wed — active recovery + skills under low intensity; justification: recovery principle — adaptation consolidates, keeps movement quality without load. Thu — agility/acceleration session with reactive cutting, short duration high quality; justification: specificity to wing movement patterns; kept fresh after recovery day (session sequencing). Fri — game-simulation training with tactical content at match intensity but reduced volume; justification: pre-competition phase sharpens match-specific fitness while beginning taper toward the weekend game — intensity maintained, volume controlled (progressive overload managed via intensity, not volume, in-season). Aerobic work appears only within recovery/game-sim: her aerobic capacity is already strong (individuality — don't spend load on a strength). Weekly structure alternates stress/recovery (hard-easy-hard) per the microcycle's load-management purpose. Marking points: (1) sessions match ATP–PC/speed diagnosis; (2) game W:R reproduced in conditioning; (3) recovery placed and justified; (4) phase-appropriate (pre-comp: intensity high, volume tapering); (5) ≥3 training principles explicitly and correctly applied; (6) aerobic strength deliberately maintained, not retrained." },
  { complexity: "complex_unfamiliar", front: "Your training strategy's mid-mesocycle data shows: sprint times improved 4%, but training-session heart-rate recovery is worsening and you feel constantly fatigued. Analyse what is happening physiologically, decide whether to maintain or modify the strategy, and justify using training and recovery principles. (5 marks)", back: "Model response: Analysis — the performance gain shows the stimulus is working (overload driving neuromuscular/ATP–PC adaptation), but declining HR recovery plus persistent fatigue are early markers of accumulating fatigue outpacing recovery — the overload has drifted past what current recovery supports (over-reaching heading toward overtraining). The two signals conflict because performance adaptations lag fatigue state: times can improve for a while even as the system degrades. Decision — modify, don't abandon: the stimulus is right, the recovery dose is wrong. Modifications: insert a deload microcycle (volume cut ~40%, intensity maintained — protects adaptations while restoring recovery capacity, per progressive overload's 'planned' requirement); audit recovery quality (sleep, active recovery sessions, nutrition); then resume progression with a hard/easy structure and monitor HR recovery weekly as the leading indicator. Justification: recovery principle — adaptation occurs in recovery, so unrecovered load stops producing gains; reversibility is not risked by a deload (short reductions preserve fitness); individuality — my monitoring data, not the template, sets the load. Reflect at mesocycle end against both sprint times and recovery markers. Marking points: (1) correctly reads conflicting indicators; (2) fatigue-vs-adaptation lag explained; (3) explicit maintain/modify decision; (4) deload specifics (volume down, intensity held); (5) ≥3 principles used accurately in justification." },
  { complexity: "complex_unfamiliar", front: "A 400 m runner (race ~55 s) asks why she can't just train like her 100 m squadmates or her cross-country friends. Using energy-system contribution ratios and interplay, explain the unique demands of her event and design the KEY conditioning set for her competition phase. (5 marks)", back: "Model response: The 400 m (~45–60 s maximal) is the archetypal lactic acid event: ATP–PC dominates only the opening seconds, the lactic system provides the largest share through the middle, and the aerobic system's contribution rises steeply in the final 15 s as anaerobic capacity saturates — roughly an even anaerobic/aerobic split by race end. 100 m training (pure ATP–PC: short efforts, full recovery) never stresses lactate tolerance; cross-country training (aerobic: long sub-maximal) never touches maximal lactic power — either alone leaves her event's dominant system undertrained (specificity). Her conditioning must generate high lactate AND teach her to keep producing force in that state. Key competition-phase set: lactate-tolerance intervals — e.g. 3 × 300 m at 95%+ race pace with 8–10 min recoveries (W:R ~1:16 for near-full quality), or split 350s (200 m + 150 m, 30 s rest); intensity maximal, volume low, frequency once–twice weekly given the recovery cost, embedded in a week that maintains speed (short sprints) and aerobic support (tempo runs) — interplay means the supporting systems still contribute to the race and to recovery between reps. Marking points: (1) correct contribution profile for ~55 s maximal work; (2) explains BOTH comparison groups' mismatch via specificity; (3) final-stage aerobic rise noted; (4) set design with justified intensity/W:R; (5) supporting systems retained — interplay applied, not a single-system program." },
  { complexity: "complex_unfamiliar", front: "You must devise a training strategy but your primary data is limited: one fitness-testing session and one videoed game. A classmate with identical results copies a professional team's program. Evaluate the classmate's approach and design how you would use your limited primary data PLUS secondary data to build a defensible strategy. (5 marks)", back: "Model response: Evaluation of copying: a professional program violates individuality (built for full-time athletes' training age, recovery capacity and support), ignores HIS data entirely, and its load assumes adaptation history he lacks — progressive overload starts from YOUR baseline, not someone else's endpoint; at best it mis-targets, at worst it injures. It also inverts the syllabus logic: strategies must be justified from primary and secondary data, not adopted then rationalised. My design: (1) extract maximum value from limited primary data — from testing: identify the two weakest position-relevant components (prioritisation); from the game video: code W:R ratios, movement frequencies/directions and late-game drop-offs (fatigue signature) to set specificity targets. (2) Use secondary data for what primary can't supply: published testing norms for my age/position (to judge whether 'weak' is genuinely weak), evidence-based training methods for the identified components, and typical loading/recovery guidelines to set safe initial overload. (3) Build the mesocycle from that synthesis, then treat the strategy as provisional: schedule re-testing and ongoing session data (RPE, times) as new primary data to justify maintaining or modifying — the small baseline is a reason for MORE built-in evaluation, not less rigour. Marking points: (1) individuality/overload critique of copying; (2) primary data mined for prioritisation AND specificity; (3) secondary data roles correctly assigned (norms, methods, loading); (4) synthesis into a program with review points; (5) framing of strategy-as-provisional showing the evaluate/justify cycle." },
  { complexity: "complex_unfamiliar", front: "A school rugby program schedules identical training for the whole squad year-round: heavy conditioning Mondays, full-contact Wednesdays, games Saturdays. Using periodisation, individuality and recovery principles, analyse THREE distinct problems with this design and propose the minimal restructure that fixes each. (6 marks)", back: "Model response: Problem 1 — no periodisation: identical year-round load means no preparatory building, no peak, no transition; players adapt fully then plateau (overload never progresses) and accumulate staleness. Fix: divide the year into phases — off-season preparatory block (build capacity), pre-season sharpening, in-season maintenance at reduced volume, post-season transition/active rest — with mesocycle-level foci. Problem 2 — recovery mis-sequencing in-season: heavy conditioning two days after games ignores that match play is the week's largest load; players train damaged, and full contact mid-week adds collision stress before recovery completes — chronic under-recovery raises injury risk (recovery principle: adaptation requires it; tapering: readiness for Saturday is the goal). Fix within the same weekly slots: Monday becomes active recovery/skills, contact volume shifts to controlled, reduced-duration technical work, and the hardest conditioning moves to the day with the longest gap from competition. Problem 3 — no individuality: forwards and backs (different energy/fitness demands), 15-year-olds and 18-year-olds (different training ages), and returning-from-injury players all receive one program — mis-targeted for most, unsafe for some. Fix: keep shared session times but split within sessions — position-group conditioning targets from separate game analyses, and load tiers (full/modified) assigned from individual testing and monitoring. Marking points: (1)–(3) three problems each tied to the correct named principle; (4)–(6) each fix minimal, specific and matched to its problem — a restructure, not a fantasy rebuild." },
];

